import Foundation

// public.users
struct AppUser: Codable {
    let id: UUID
    let username: String
}

// public.health_profiles
struct HealthProfile: Codable {
    let user_id: UUID
    let age: Int
    let height_inches: Double
    let biological_sex: String
}

// Used when inserting a new weight
// Supabase generates id and recorded_at
struct NewWeightLog: Encodable {
    let user_id: UUID
    let weight_lbs: Double
}

// This table is used when the user is setting their goal
// Supabase will create an id, status, and created_at
struct NewGoal: Encodable {
    let user_id: UUID
    let goal_type: String
    let starting_value: Double
    let target_value: Double
    let unit: String

    // Optional date for completing the goal
    var target_date: String? = nil
}


// This table will grab the latest weight from Supabase
struct CurrentWeight: Decodable {
    let weight_lbs: Double
}

// This table will show the user's current goal from Supabase
struct CurrentGoal: Decodable {
    let goal_type: String
    let starting_value: Double
    let target_value: Double
    let unit: String
    let status: String

    // Goal completion or review date from Supabase
    let target_date: String?
}


// This table stores the user's daily health data
struct HealthDailyStat: Codable {
    let user_id: UUID
    let stat_date: String
    let steps: Int
    let active_calories: Double
    let resting_calories: Double
}

// Used when user logs their food
struct NewFoodLog: Encodable {
    
    let user_id: UUID
    let source: String
    let fdc_id: Int?
    let food_name: String
    let brand_name: String?
    
    let serving_amount: Double
    let serving_unit: String
    
    // Core nutrition
    let calories: Double
    let protein_g: Double
    let carbs_g: Double
    let fat_g: Double
    
    // Additional nutrition
    let fiber_g: Double?
    let sugar_g: Double?
    let saturated_fat_g: Double?
    let trans_fat_g: Double?
    let sodium_mg: Double?
    let cholesterol_mg: Double?
    
    let meal_type: String
    let consumed_at: String
}

// Represents an existing food_logs row
// Used when reading food logs back from Supabase
struct FoodLog: Decodable, Identifiable {
    
    let id: UUID
    let user_id: UUID
    let source: String
    let fdc_id: Int?
        
    let food_name: String
    let brand_name: String?
    
    let serving_amount: Double
    let serving_unit: String
        
    // Core nutrition
    let calories: Double
    let protein_g: Double
    let carbs_g: Double
    let fat_g: Double
        
    // Additional nutrition
    let fiber_g: Double?
    let sugar_g: Double?
    let saturated_fat_g: Double?
    let trans_fat_g: Double?
    let sodium_mg: Double?
    let cholesterol_mg: Double?
        
    let meal_type: String?
    let consumed_at: String
}


